"""
@brief Demonstrate the log control functionality.
This function demonstrates how to use various logging control functions to manage the logging behavior of a DLL.
It includes starting and stopping logging to files, setting log levels, and receiving real-time device logs.

@return void
"""
from SGxxxDemoParam import ConstantParam
from DLLLoadManage import hDLL

def DemoLOGControl():
    Param = ConstantParam()
    #The path provided after OpteeQ_StartLogToFile serves to redirect the logs generated by the OpteeQ DLL module to the specified “local” file.
    hDLL.StartLogToFile(bytes('./OpteeQDLL.log', encoding='utf-8'))       #change the log file(DLL log)
    hDLL.SetLogLevel(5)      #show none log(DLL log)
    hDLL.SetLogLevel(0)      #show all log(DLL log)
    hDLL.SetLogLevel(1)      #show info log(DLL log)
    hDLL.StopLogToConsole()  #stop log to the console window
    #hDLL.StopLog();         #stop the log(DLL log)
    hDLL.ReceiveDevLog(bytes(Param.PROGRAMMER_TEST, encoding='utf-8'), bytes('./DeviceLog.log', encoding='utf-8'))           #receive the real-time logs of the device to the specified file
    hDLL.ChangeLogFile(bytes(Param.PROGRAMMER_TEST, encoding='utf-8'), bytes('./ProgrammerLog.txt', encoding='utf-8'))       #change the real-time logs of the device to the specified file
    hDLL.StopDevLog(bytes(Param.PROGRAMMER_TEST, encoding='utf-8'))       #stop receiving real-time logs